() => {
  const text = document.body ? document.body.innerText.slice(0, 8000) : '';
  const scripts = [...document.querySelectorAll('script')].map(s => s.id || s.type).slice(0, 50);
  const hasRedux = !!(window.__INITIAL_STATE__ || window.__PRELOADED_STATE__);
  const meta = [...document.querySelectorAll('[data-testid], h1, a')].slice(0, 30).map(el => ({tag: el.tagName, testid: el.getAttribute('data-testid'), text: (el.textContent||'').trim().slice(0,80)}));
  return { text, scripts, hasRedux, meta };
}

async () => {
  const urls = [
    'https://bitbucket.org/!api/2.0/repositories/healshealthcare/csx-mobile/pullrequests/538',
    'https://bitbucket.org/!api/2.0/repositories/healshealthcare/csx-mobile/pullrequests/538/diffstat',
    'https://bitbucket.org/!api/2.0/repositories/healshealthcare/csx-mobile/pullrequests/538/commits'
  ];
  const results = {};
  for (const url of urls) {
    const res = await fetch(url, { credentials: 'include' });
    const text = await res.text();
    results[url] = { status: res.status, body: text.slice(0, 20000) };
  }
  return results;
}

