const ts = require('typescript');
const path = require('path');
const fs = require('fs');

const cwd = process.cwd();
const configPath = path.join(cwd, 'tsconfig.json');
const configFile = ts.readConfigFile(configPath, ts.sys.readFile);
if (configFile.error) {
  console.error('readConfigFile', ts.flattenDiagnosticMessageText(configFile.error.messageText, '\n'));
  process.exit(1);
}
const parsed = ts.parseJsonConfigFileContent(configFile.config, ts.sys, cwd);
console.log('parseErrors', parsed.errors.length);
console.log('fileCount', parsed.fileNames.length);
const program = ts.createProgram({
  rootNames: parsed.fileNames,
  options: { ...parsed.options, incremental: false, tsBuildInfoFile: undefined },
});

const changedRel = [
  'src/api/api-types.ts',
  'src/api/api.ts',
  'src/pages/NewlyAddedPatients/NewlyAddedPatients.styles.ts',
  'src/pages/NewlyAddedPatients/NewlyAddedPatients.tsx',
];
const changedAbs = new Set(changedRel.map((f) => path.resolve(cwd, f)));

function printDiag(d, sf) {
  const file = d.file || sf;
  let loc = '';
  if (file && typeof d.start === 'number') {
    const pos = file.getLineAndCharacterOfPosition(d.start);
    loc = `${file.fileName}:${pos.line + 1}:${pos.character + 1}`;
  } else {
    loc = (file && file.fileName) || '<no-file>';
  }
  const msg = ts.flattenDiagnosticMessageText(d.messageText, '\n');
  const cat = ts.DiagnosticCategory[d.category];
  console.log(`${loc} [${cat}] TS${d.code} ${msg}`);
}

for (const rel of changedRel) {
  const abs = path.resolve(cwd, rel);
  const sf = program.getSourceFile(abs);
  console.log('\n==== FILE', rel, 'sourceFile=', !!sf, '====');
  if (!sf) continue;
  const syn = program.getSyntacticDiagnostics(sf);
  const sem = program.getSemanticDiagnostics(sf);
  const sug = program.getSuggestionDiagnostics(sf);
  console.log('syntactic', syn.length, 'semantic', sem.length, 'suggestion', sug.length);
  for (const d of [...syn, ...sem]) printDiag(d, sf);
  for (const d of sug) printDiag(d, sf);
}

// Also print global config diagnostics that mention changed files
const globalDiags = ts.getPreEmitDiagnostics(program).filter((d) => d.file && changedAbs.has(path.resolve(d.file.fileName)));
console.log('\n==== preEmit intersection count', globalDiags.length, '====');
EOF
